// Polyfill worker_threads.markAsUncloneable for Node.js < 21 compatibility (specifically Node 20.20.2)
import worker_threads from "node:worker_threads";
import { WebSocket } from "ws";

if (worker_threads && !worker_threads.markAsUncloneable) {
  (worker_threads as any).markAsUncloneable = function (obj: any) {
    if (worker_threads.markAsUntransferable) {
      try {
        worker_threads.markAsUntransferable(obj);
      } catch {
        // no-op
      }
    }
  };
}

// Polyfill Promise.withResolvers for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof Promise.withResolvers === "undefined") {
  Promise.withResolvers = function <T>() {
    let resolve!: (value: T | PromiseLike<T>) => void;
    let reject!: (reason?: any) => void;
    const promise = new Promise<T>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve, reject };
  } as any;
}

// Polyfill WebSocket for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof globalThis.WebSocket === "undefined") {
  (globalThis as any).WebSocket = WebSocket;
}

// Test-only DATA_DIR isolation.
//
// Loaded via `node --import ./tests/_setup/isolateDataDir.ts` from the test/mutation
// invocations (package.json test scripts, stryker.conf.json tap.nodeArgs, the
// quality.yml TIA step, and the CI test jobs) — NEVER from production. It MUST stay
// out of open-sse/utils/setupPolyfill.ts, which is also imported by production
// (bin/omniroute.mjs, proxyFetch.ts, proxyDispatcher.ts) where redirecting DATA_DIR
// would point the live SQLite DB at a throwaway temp dir.
//
// Why: node:test spawns a process per test file and Stryker spawns one per sandbox,
// but every process resolves DATA_DIR to the SAME default (~/.omniroute) when the env
// var is unset (see src/lib/dataPaths.ts::resolveDataDir). Concurrent processes then
// open the SAME on-disk storage.sqlite, causing cross-file state races: SQLite lock
// contention that hangs `test:unit` under high `--test-concurrency`, and the
// non-deterministic baseline that forced Stryker to `concurrency: 1`.
//
// Giving each process its own DATA_DIR under the OS temp dir removes the shared file,
// so concurrent test processes never collide. Tests that set DATA_DIR explicitly keep
// winning — this only fills in an isolated default when none was chosen.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

// File logger worker threads can outlive a test's temporary DATA_DIR cleanup and then
// raise ENOENT/ENOTEMPTY after the test has already passed. Keep the global test default
// console-only; tests that cover file logging explicitly set APP_LOG_TO_FILE themselves.
process.env.APP_LOG_TO_FILE ||= "false";

if (!process.env.DATA_DIR) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "omniroute-test-"));
  process.env.DATA_DIR = dir;

  // Best-effort cleanup so a long suite run does not leak hundreds of temp DBs.
  process.on("exit", () => {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // ignore — the OS reaps its temp dir eventually.
    }
  });
}

// System-trust guard: the suite must NEVER mutate the OS trust store. On a
// persistent self-hosted runner the cert-flow integration test installed a fake
// 105-byte PEM into /usr/local/share/ca-certificates and update-ca-certificates
// baked it into the bundle, breaking ALL system TLS on the VM (2026-07-05).
// installCert/uninstallCert/installTproxyCa/uninstallTproxyCa no-op under this.
process.env.OMNIROUTE_SKIP_SYSTEM_TRUST = "1";

// DNS-write guard: the suite must NEVER mutate /etc/hosts. Tests that exercise
// the real MITM path call addDNSEntries(); this env var makes it a no-op.
process.env.OMNIROUTE_SKIP_DNS_WRITE = "1";

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const TEST_DIR = fs.mkdtempSync(path.join(os.tmpdir(), "omni-deliveries-"));
process.env.DATA_DIR = TEST_DIR;

const coreDb = await import("../../src/lib/db/core.ts");
const webhooksDb = await import("../../src/lib/db/webhooks.ts");
const deliveriesDb = await import("../../src/lib/db/webhookDeliveries.ts");

async function resetStorage() {
  coreDb.resetDbInstance();
  fs.rmSync(TEST_DIR, { recursive: true, force: true });
  fs.mkdirSync(TEST_DIR, { recursive: true });
}

test.beforeEach(async () => {
  await resetStorage();
});

test.after(() => {
  coreDb.resetDbInstance();
  fs.rmSync(TEST_DIR, { recursive: true, force: true });
});

test("insertDelivery stores a row and getDeliveries returns it", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  deliveriesDb.insertDelivery({
    webhookId: wh.id,
    eventType: "request.failed",
    status: "delivered",
    httpStatus: 200,
    latencyMs: 142,
    payloadSnapshot: JSON.stringify({ event: "request.failed" }),
  });
  const rows = deliveriesDb.getDeliveries(wh.id, 10);
  assert.equal(rows.length, 1);
  assert.equal(rows[0].event_type, "request.failed");
  assert.equal(rows[0].http_status, 200);
  assert.equal(rows[0].latency_ms, 142);
  assert.equal(rows[0].status, "delivered");
  assert.equal("payload_snapshot" in rows[0], false);
});

test("rotation keeps only last 100 deliveries per webhook", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  for (let i = 0; i < 105; i++) {
    deliveriesDb.insertDelivery({
      webhookId: wh.id,
      eventType: "test.ping",
      status: "delivered",
      httpStatus: 200,
      latencyMs: 10,
    });
  }
  const rows = deliveriesDb.getDeliveries(wh.id, 200);
  assert.equal(rows.length, 100);
});

test("getDeliveries respects limit parameter", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  for (let i = 0; i < 10; i++) {
    deliveriesDb.insertDelivery({
      webhookId: wh.id,
      eventType: "test.ping",
      status: "delivered",
      httpStatus: 200,
      latencyMs: 10,
    });
  }
  const rows = deliveriesDb.getDeliveries(wh.id, 5);
  assert.equal(rows.length, 5);
});

test("CASCADE delete removes deliveries when webhook is deleted", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  deliveriesDb.insertDelivery({
    webhookId: wh.id,
    eventType: "test.ping",
    status: "delivered",
    httpStatus: 200,
    latencyMs: 10,
  });
  webhooksDb.deleteWebhook(wh.id);
  const rows = deliveriesDb.getDeliveries(wh.id, 10);
  assert.equal(rows.length, 0);
});

test("createWebhook uses kind=custom by default", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  assert.equal(wh.kind, "custom");
  assert.equal(wh.metadata_encrypted, null);
});

test("createWebhook accepts kind=slack", () => {
  const wh = webhooksDb.createWebhook({
    url: "https://hooks.slack.com/services/T/B/xxx",
    kind: "slack",
  });
  assert.equal(wh.kind, "slack");
});

test("updateWebhook can change kind and metadataEncrypted", () => {
  const wh = webhooksDb.createWebhook({ url: "https://example.com/hook" });
  const updated = webhooksDb.updateWebhook(wh.id, {
    kind: "telegram",
    metadataEncrypted: "enc:v1:test",
  });
  assert.equal(updated?.kind, "telegram");
  assert.equal(updated?.metadata_encrypted, "enc:v1:test");
});

/**
 * db/core.js — Database infrastructure: schema, singleton, utils, migration.
 *
 * All domain modules import `getDbInstance` and helpers from here.
 */

import type { SqliteAdapter } from "./adapters/types";
import {
  tryOpenSync,
  getSqlJsAdapter,
  preInitSqlJs,
  getSqlJsPreInitError,
  openDatabaseAsync,
} from "./adapters/driverFactory";
import path from "path";
import fs from "fs";
import { resolveWritableDataDir, getLegacyDotDataDir } from "../dataPaths";
import { runMigrations } from "./migrationRunner";
import { runDbHealthCheck } from "./healthCheck";
import { resetAllDbModuleState } from "./stateReset";
import { parseStoredPayload } from "../logPayloads";
import { DEFAULT_DATABASE_SETTINGS, type DatabaseSettings } from "@/types/databaseSettings";
import {
  applyDatabaseOptimizationSettingsForDb,
  applyStoredDatabaseOptimizationSettings,
  getAutoVacuumModeForDb,
  setAutoVacuumForDb,
  setCacheSizeForDb,
  setPageSizeForDb,
} from "./optimizationSettings";
import {
  buildArtifactRelativePath,
  writeCallArtifact,
  type CallLogArtifact,
} from "../usage/callLogArtifacts";
import { migrateLegacyEncryptedString } from "./encryption";
import { invalidateDbCache } from "./readCache";
import { rowToCamel } from "./caseMapping";
import { isAutomatedTestProcess } from "@/shared/utils/testProcess";
// Re-exported so existing call sites that pull these helpers off the core module keep working.
export { toSnakeCase, toCamelCase, objToSnake, rowToCamel, cleanNulls } from "./caseMapping";
import {
  ensureProviderConnectionsColumns,
  ensureUsageHistoryAccountIndex,
  ensureUsageHistoryColumns,
  ensureCallLogsColumns,
  hasTable,
  quoteIdentifier,
  getTableColumns,
} from "./schemaColumns";

type SqliteDatabase = SqliteAdapter;
type JsonRecord = Record<string, unknown>;
type CheckpointMode = "PASSIVE" | "FULL" | "RESTART" | "TRUNCATE";
type DatabaseOptimizationSettings = DatabaseSettings["optimization"];
type PreservedTableSnapshot = {
  table: string;
  rowCount: number;
  maxRows: number;
  columns: string[];
  rows: JsonRecord[];
};
type SkippedTableSnapshot = {
  table: string;
  rowCount: number;
  maxRows: number;
  reason: string;
};
type PreservedCriticalDbState = {
  captureSucceeded: boolean;
  captureError: string | null;
  preservedTables: PreservedTableSnapshot[];
  skippedTables: SkippedTableSnapshot[];
};
type CriticalTableSpec = {
  table: string;
  maxRows?: number;
  readRows?: (db: SqliteDatabase) => JsonRecord[];
};

// ──────────────── Environment Detection ────────────────

export const isCloud = typeof globalThis.caches === "object" && globalThis.caches !== null;

export const isBuildPhase = process.env.NEXT_PHASE === "phase-production-build";

// ──────────────── Paths ────────────────

export const DATA_DIR = resolveWritableDataDir({ isCloud });
const LEGACY_DATA_DIR = isCloud ? null : getLegacyDotDataDir();
export const SQLITE_FILE = isCloud ? null : path.join(DATA_DIR, "storage.sqlite");
const JSON_DB_FILE = isCloud ? null : path.join(DATA_DIR, "db.json");
export const DB_BACKUPS_DIR = isCloud ? null : path.join(DATA_DIR, "db_backups");
const DEFAULT_CRITICAL_TABLE_ROW_LIMIT = 10_000;
const SKIP_PRESERVE_NAMESPACES = new Set([
  "syncedAvailableModels",
  "providerLimitsCache",
  "lkgp",
  "gemini_thought_signatures",
]);
const CRITICAL_DB_TABLES: CriticalTableSpec[] = [
  {
    table: "key_value",
    maxRows: 10_000,
    readRows(db) {
      return (
        (db.prepare("SELECT namespace, key, value FROM key_value").all() as JsonRecord[]) ?? []
      ).filter(
        (row) => typeof row.namespace !== "string" || !SKIP_PRESERVE_NAMESPACES.has(row.namespace)
      );
    },
  },
  { table: "provider_connections", maxRows: 5_000 },
  { table: "provider_nodes", maxRows: 5_000 },
  { table: "combos", maxRows: 5_000 },
  { table: "api_keys", maxRows: 5_000 },
  { table: "proxy_registry", maxRows: 5_000 },
  { table: "proxy_assignments", maxRows: 10_000 },
  { table: "model_combo_mappings", maxRows: 5_000 },
  { table: "sync_tokens", maxRows: 5_000 },
  { table: "registered_keys", maxRows: 10_000 },
  { table: "provider_key_limits", maxRows: 10_000 },
  { table: "account_key_limits", maxRows: 10_000 },
  { table: "upstream_proxy_config", maxRows: 5_000 },
  { table: "webhooks", maxRows: 5_000 },
];

export function isNativeSqliteLoadError(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  const code = getErrorCode(error);
  return (
    message.includes("Module did not self-register") ||
    message.includes("NODE_MODULE_VERSION") ||
    message.includes("ERR_DLOPEN_FAILED") ||
    // bun and similar runtimes that skip the postinstall script never download
    // the prebuilt *.node binary, so `bindings()` fails with this message
    // before any DLOPEN even happens (#2358).
    message.includes("Could not locate the bindings file") ||
    message.includes("Cannot find module 'better-sqlite3'") ||
    code === "ERR_DLOPEN_FAILED" ||
    code === "MODULE_NOT_FOUND"
  );
}

export function isSqliteDriverUnavailableError(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);

  return (
    message.includes("Nenhum driver SQLite disponível") ||
    message.includes("Chame ensureDbInitialized() no startup") ||
    message.includes("sql.js WASM ainda não foi pré-inicializado")
  );
}

function getErrorCode(error: unknown): string | undefined {
  if (!error || typeof error !== "object" || !("code" in error)) return undefined;
  const code = (error as { code?: unknown }).code;
  return typeof code === "string" ? code : undefined;
}

/**
 * Closes a probe/throwaway connection obtained from `openSqliteDatabase()` —
 * but ONLY when it is safe to do so. better-sqlite3/node:sqlite hand back an
 * independent handle per open() call, so closing a probe never affects a
 * later "real" connection to the same file. sql.js has no such notion: its
 * fallback path (`getSqlJsAdapter()`) always returns the SAME module-global
 * cached singleton for a given filePath, so closing "the probe" closes the
 * ONLY connection that file will ever get until process restart — every
 * subsequent query (including the "real" connection opened right after)
 * throws sql.js's raw "Database closed" string (#7494). Skip the close for
 * sql.js and let the same live adapter flow through untouched.
 */
export function closeProbeIfSafe(adapter: SqliteDatabase | null | undefined): void {
  if (!adapter || adapter.driver === "sql.js") return;
  if (adapter.open) adapter.close();
}

function openSqliteDatabase(sqliteFile: string, options?: Record<string, unknown>): SqliteDatabase {
  const adapter = tryOpenSync(sqliteFile, options);
  if (adapter) return adapter;

  const sqlJs = getSqlJsAdapter(sqliteFile);
  if (sqlJs) return sqlJs;

  // sql.js pre-init was genuinely attempted (e.g. by the top-level eager
  // barrier below) and failed — surface the real cause instead of the
  // generic/misleading "not pre-initialized yet" message (#7288).
  const preInitError = getSqlJsPreInitError(sqliteFile);
  const syncDrivers = process.versions.bun
    ? "bun:sqlite (failed)"
    : "better-sqlite3 (failed), node:sqlite (unavailable)";
  if (preInitError) {
    throw new Error(
      `[DB] Nenhum driver SQLite disponível para '${sqliteFile}'. ` +
        `Drivers testados: ${syncDrivers}, ` +
        `sql.js (falhou: ${preInitError}).`
    );
  }

  throw new Error(
    `[DB] Nenhum driver SQLite disponível para '${sqliteFile}'. ` +
      "Chame ensureDbInitialized() no startup. " +
      `Drivers testados: ${syncDrivers}. ` +
      "sql.js WASM ainda não foi pré-inicializado."
  );
}

// Ensure data directory exists — with fallback for restricted home directories (#133)
if (!isCloud && !fs.existsSync(DATA_DIR)) {
  try {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.warn(
      `[DB] Cannot create data directory '${DATA_DIR}': ${msg}\n` +
        `[DB] Set the DATA_DIR environment variable to a writable path, e.g.:\n` +
        `[DB]   DATA_DIR=/path/to/writable/dir omniroute`
    );
  }
}

